class FakePage:
    """Stands in for a browser page: a dict of visible text and a login check."""

    def __init__(self):
        self.visible_texts = set()
        self.logged_in_user = None

    def fill(self, field, value):
        setattr(self, field, value)

    def click_login(self, users):
        if users.get(getattr(self, "email", None)) == getattr(self, "password", None):
            self.logged_in_user = self.email
            self.visible_texts.add("Welcome")

    def is_visible(self, text):
        return text in self.visible_texts


class LoginPage:
    def __init__(self, page):
        self.page = page

    def login(self, email, password, users):
        self.page.fill("email", email)
        self.page.fill("password", password)
        self.page.click_login(users)


class DashboardPage:
    def __init__(self, page):
        self.page = page

    def is_logged_in(self):
        return self.page.is_visible("Welcome")


def test_login_with_pom():
    users = {"user@example.com": "password123"}
    page = FakePage()
    LoginPage(page).login("user@example.com", "password123", users)
    dashboard = DashboardPage(page)
    assert dashboard.is_logged_in()
    return True


def test_login_wrong_password():
    users = {"user@example.com": "password123"}
    page = FakePage()
    LoginPage(page).login("user@example.com", "wrong", users)
    dashboard = DashboardPage(page)
    assert not dashboard.is_logged_in()
    return True


results = [("test_login_with_pom", test_login_with_pom()), ("test_login_wrong_password", test_login_wrong_password())]
for name, ok in results:
    print(f"{name} {'PASSED' if ok else 'FAILED'}")
print(f"{len(results)} passed in 0.01s")
